-- NARAKU SERVERBROWSER RBXM HARD-CODE
-- Source: ServerBrowser.rbxm
-- Embedded RBXM payload + generic InsertAsset logic

local Workspace = game:GetService("Workspace")
local SerializationService = game:GetService("SerializationService")

local BASE64 = table.concat({
    "",\n    "",\n    "",\n    "",\n    "",\n    "",\n    "",\n    "",\n    "",\n    "",\n    ""
})

local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map = {}
for i = 1, #alphabet do
    map[string.sub(alphabet, i, i)] = i - 1
end

local function decodeBase64(s)
    local out, n, buffer, bits = {}, 0, 0, 0
    for i = 1, #s do
        local ch = string.sub(s, i, i)
        if ch ~= "=" then
            local v = map[ch]
            if v then
                buffer = buffer * 64 + v
                bits += 6
                if bits >= 8 then
                    bits -= 8
                    n += 1
                    out[n] = string.char(math.floor(buffer / (2 ^ bits)) % 256)
                    buffer = buffer % (2 ^ bits)
                end
            end
        end
    end
    return table.concat(out)
end

local rawData = decodeBase64(BASE64)
local bufferData = buffer.fromstring(rawData)

local ok, instances = pcall(function()
    return SerializationService:DeserializeInstancesAsync(bufferData)
end)

if not ok then
    error("ServerBrowser RBXM deserialize failed: " .. tostring(instances))
end

-- =========================================================
-- GENERIC INSERT ASSET
-- =========================================================
local function InsertAsset(assetName, statusTarget)
    assetName = tostring(assetName or "ServerBrowser"):gsub("%.rbxm$", "")

    local function status(text)
        if statusTarget then
            pcall(function() statusTarget.Text = text end)
        end
    end

    status("Working")

    -- Optional server-backed path for a server you control.
    local loadRemote = rawget(_G, "LoadAssetRemote")
    local clearRemote = rawget(_G, "ClearAssetRemote")
    local playerGui = rawget(_G, "PlayerGui")

    if loadRemote and loadRemote:IsA("RemoteFunction") and playerGui then
        local requestOK, result = pcall(function()
            return loadRemote:InvokeServer(assetName)
        end)

        if not requestOK or not result then
            status("Gagal")
            return false, result or "Server request failed"
        end

        local folder = playerGui:WaitForChild(assetName, 10)
        if not folder then
            status("No Asset")
            return false, "Asset was not returned"
        end

        local clone = folder:Clone()
        local children = clone:GetChildren()

        if #children == 0 then
            clone:Destroy()
            status("Empty")
            return false, "Asset is empty"
        end

        local count = 0
        for _, obj in ipairs(children) do
            obj.Parent = Workspace
            count += 1
        end

        clone:Destroy()

        if clearRemote and clearRemote:IsA("RemoteFunction") then
            pcall(function()
                clearRemote:InvokeServer(assetName)
            end)
        end

        status("Inserted: " .. count)
        return true, count
    end

    -- Embedded RBXM fallback.
    local count = 0
    for _, instance in ipairs(instances) do
        if instance and instance.Parent == nil then
            instance.Parent = Workspace
            count += 1
        end
    end

    if count == 0 then
        status("Already Inserted")
        return false, "No unparented root instances available"
    end

    status("Inserted: " .. count)
    return true, count
end

